  'ad_hazardous_materials': [
    _AbuDhabiSection(
      title: 'Inventory & Classification',
      icon: Icons.warning_amber_outlined,
      items: [
        'For hazardous materials, define the scope of inventory and classification before work starts and identify the people, equipment, materials and interfaces that can be affected.',
        'Apply the current ADOSH-SF requirements relevant to hazardous materials and translate them into clear project controls, responsibilities and verification criteria.',
        'Use the hierarchy of controls for inventory and classification: eliminate or reduce the hazard first, then use engineering, administrative and PPE controls as appropriate.',
        'Ensure competent personnel understand inventory and classification, have the required information and equipment, and know the conditions that require work to stop or be reassessed.',
        'Inspect and document the condition of controls for inventory and classification; defects, deviations or changing conditions should be corrected, escalated and reverified.',
