        'Unsafe: Lock only the electrical isolator while hydraulic, pneumatic, gravity or stored energy remains available.',
        'Safe: Each authorised worker applies their own required lock where the procedure calls for personal control.',
        'Unsafe: Use one shared lock or rely on a verbal agreement between shifts.',
        'Safe: Release stored energy and verify the equipment cannot start or move before hands enter the danger zone.',
        'Unsafe: Test only the start button and assume all energy has been controlled without a systematic verification.',
